SELECT
-- UNIMARC/A. Paramètre Après AuthID : commencer à 0. Lecture seule.
 a.authid AS AuthID,a.authtypecode AS Type,COALESCE(NULLIF(a.heading,''),TRIM(CONCAT_WS(' ',NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="200"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="210"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="215"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="216"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="220"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="230"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="235"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="240"]/subfield'),' '),NULLIF(ExtractValue(a.marcxml,'//datafield[@tag="250"]/subfield'),' ')))) AS Vedette,a.datecreated AS datecreated,a.modification_time AS modification_time FROM auth_header a WHERE a.authid > <<Après AuthID>> ORDER BY a.authid ASC LIMIT 1000
